cd . && node -e '
const fs=require("fs");
for(let k=1;k<=32;k++){
  let body;
  const m=k%4;
  if(m===1) body=`  return (v + Math.floor(v / 3)) % 997;`;
  else if(m===2) body=`  return v ^ ((i * 7) % 64);`;
  else if(m===3) body=`  return (v * 3 - i) % 991;`;
  else body=`  return (v * 2 + 1) % 1000;`;
  const pre=(m===2||m===3)?`  const i = ${k};\n`:"";
  const src=`// 第 ${k} 级流水线的一段：吃上一级的输出，吐给下一级\nexport function step${k}(v) {\n${pre}${body}\n}\n`;
  fs.writeFileSync(`src/s${String(k).padStart(2,"0")}.js`,src);
}
console.log("written");
' && npm test

